      out.write("		//위의 news는 js의 객체 이므로 그 자체론 전송 불가 따라서 문자열화 시켜야 함\r\n");
      out.write("		//개발자가 손수 쌍따옴표로 감싸지 말고 JSON 내장 객체의 자동 문자열화 메서드인 stringify() 를 ㅣ용하자!\r\n");
