      out.write("		//async/await 는 사실 내부에 Promise 수행 되기는 하나, 개발자가 then() 을 여러개\r\n");
      out.write("		//체이닝하여 코드를 작성하는 것 자체가 복잡하므로, 이 과정을 마치 동기 방식처럼 숨겨 놓은 기술\r\n");
      out.write("		//여전히 fetch() 문에 의해 Promise 가 반환되지만,서버로부터 응답이 없을 경우의 처리를\r\n");
      out.write("		//개발자가 직접 처리할 필요없으며 응답이 없을 경우 알아서 catch문을 수행함\r\n");
